/* JUHANI Premium Animated Search */

selector .e-search-form {
    gap: 8px;
    align-items: stretch;
}

/* Search input */
selector .e-search-input {
    background: #F7FAFC !important;
    color: #173B5E !important;
    border: 1px solid #DCE7F0 !important;
    
    min-height: 48px;
    padding: 12px 16px !important;
    transition: background .3s ease,
                border-color .3s ease,
                box-shadow .3s ease;
}

/* Placeholder */
selector .e-search-input::placeholder {
    color: #8294A5;
    opacity: 1;
}

/* Click / Focus Animation */
selector .e-search-input:focus {
    background: #FFFFFF !important;
    border-color: #259DD8 !important;
    box-shadow: 0 0 0 4px rgba(37,157,216,.12) !important;
    outline: none !important;
}

/* Search Button */
selector .e-search-submit {
    background: #123B60 !important;
    color: #FFFFFF !important;
    border: none !important;
    
    min-height: 48px;
    padding: 0 22px !important;
    cursor: pointer;
    transition: background .3s ease,
                transform .3s ease,
                box-shadow .3s ease;
}

/* Button Hover Animation */
selector .e-search-submit:hover {
    background: #168FD0 !important;
    transform: translateY(-2px);
    box-shadow: 0 6px 16px rgba(22,143,208,.22);
}

/* Button Click */
selector .e-search-submit:active {
    transform: translateY(0);
    box-shadow: none;
}

/* Keyboard Accessibility */
selector .e-search-submit:focus-visible {
    outline: 3px solid #66B9E8;
    outline-offset: 2px;
}

/* Mobile */
@media (max-width: 767px) {
    selector .e-search-submit {
        padding: 0 14px !important;
    }
}

/* Reduce Motion */
@media (prefers-reduced-motion: reduce) {
    selector .e-search-input,
    selector .e-search-submit {
        transition: none;
    }
}
